package com.dbagent.store;

/**
 * 레지스트리의 컬럼 타입. 실제 DDL 타입은 방언이 정한다(설계서 2.5절).
 * <ul>
 *   <li>VARCHAR - H2 VARCHAR(n) / Oracle VARCHAR2(n CHAR). 길이가 1333을 넘으면 Oracle에서는 CLOB
 *       (운영 MAX_STRING_SIZE=STANDARD라 4000바이트 상한, 한글 3바이트).</li>
 *   <li>TEXT_LARGE - H2 VARCHAR(n) / Oracle CLOB. 비교·GROUP BY에 쓰지 않는 컬럼만.</li>
 *   <li>BOOL01 - 0/1 값. H2 INTEGER / Oracle NUMBER(1).</li>
 *   <li>IDENTITY - 자동 증가 키. H2 BIGINT AUTO_INCREMENT / Oracle NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY.</li>
 * </ul>
 */
public enum ColType {
    VARCHAR, TEXT_LARGE, BIGINT, INTEGER, DOUBLE, BOOL01, IDENTITY
}
